using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Records")]
    [TestClass]
    public class RJIT_CR_R_00003 : ControllerTestBase
    {
        [TestMethod]
        public void Records_Have_To_Use_IImmutable_List_Types()
        {
            var mutableProperties = (from syntaxTree in SyntaxTreesToAnalyze
                                     from @record in syntaxTree.Records
                                     from property in @record.Properties
                                     from forbiddenType in RecordExtensions.ForbiddenListTypes
                                     where property.Type.StartWith(forbiddenType)
                                     select new
                                     {
                                         Error = $@"

Please use IImmutableList or FrozenCollections for your properties which represents a set of data. And Initialize them correctly of they are optional.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullName:  {@record.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Property:  {property.Type} {property.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Record:

{@record.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{@record.ToImmutableListProperties()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                     }).ToImmutableList();

            Assert.IsTrue(mutableProperties.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_R_00003

Any list types must be immutable as well. Findings: '{mutableProperties.Count}':{Environment.NewLine}{mutableProperties.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
